import { PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { randomUUID } from "node:crypto";

export const MAX_IMAGE_BYTES = 5 * 1024 * 1024;

// Detected from magic bytes, never from the client-supplied type. SVG is
// deliberately excluded: it can carry scripts.
const IMAGE_TYPES = {
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/gif": "gif",
  "image/webp": "webp",
} as const;

type ImageType = keyof typeof IMAGE_TYPES;

export class UploadError extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
  }
}

function sniffImageType(b: Buffer): ImageType | null {
  if (b.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return "image/png";
  if (b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return "image/jpeg";
  if (b.subarray(0, 4).toString("ascii") === "GIF8") return "image/gif";
  if (b.subarray(0, 4).toString("ascii") === "RIFF" && b.subarray(8, 12).toString("ascii") === "WEBP") return "image/webp";
  return null;
}

function env(name: string): string {
  const v = process.env[name];
  if (!v) throw new Error(`Missing env var ${name}`);
  return v;
}

let client: S3Client | undefined;
function s3(): S3Client {
  // Works with AWS S3, Cloudflare R2, MinIO, etc. via S3_ENDPOINT.
  client ??= new S3Client({
    region: process.env.S3_REGION ?? "auto",
    endpoint: process.env.S3_ENDPOINT || undefined,
    forcePathStyle: Boolean(process.env.S3_ENDPOINT),
    credentials: {
      accessKeyId: env("S3_ACCESS_KEY_ID"),
      secretAccessKey: env("S3_SECRET_ACCESS_KEY"),
    },
  });
  return client;
}

/** Validates and stores an image; returns its public URL. */
export async function uploadImage(file: File, userId: string): Promise<string> {
  if (file.size === 0) throw new UploadError("Empty file", 400);
  if (file.size > MAX_IMAGE_BYTES) throw new UploadError("Image must be 5 MB or smaller", 413);

  const body = Buffer.from(await file.arrayBuffer());
  const type = sniffImageType(body);
  if (!type) throw new UploadError("Only PNG, JPEG, GIF or WebP images are allowed", 415);

  const key = `notes/${userId}/${randomUUID()}.${IMAGE_TYPES[type]}`;
  await s3().send(
    new PutObjectCommand({
      Bucket: env("S3_BUCKET"),
      Key: key,
      Body: body,
      ContentType: type,
      CacheControl: "public, max-age=31536000, immutable",
    }),
  );

  return `${env("S3_PUBLIC_BASE_URL").replace(/\/$/, "")}/${key}`;
}
EOF
