import { randomUUID } from "node:crypto";

export type Note = {
  id: string;
  userId: string;
  text: string;
  imageUrl?: string;
  createdAt: string;
};

// In-memory like src/lib/users.ts; swap for a real DB later.
const notes: Note[] = [];

export async function listNotesForUser(userId: string): Promise<Note[]> {
  return notes.filter((n) => n.userId === userId);
}

export async function createNote(userId: string, text: string): Promise<Note> {
  const note: Note = { id: randomUUID(), userId, text, createdAt: new Date().toISOString() };
  notes.push(note);
  return note;
}

export async function getNote(id: string): Promise<Note | undefined> {
  return notes.find((n) => n.id === id);
}

export async function setNoteImage(id: string, imageUrl: string): Promise<void> {
  const note = notes.find((n) => n.id === id);
  if (note) note.imageUrl = imageUrl;
}
